1	// pattern: Mixed (Functional Core types + Imperative Shell commands)
2	//
3	// Permanent identity removal: the wallet-side counterpart to the PDS's
4	// `requestAccountDelete`/`deleteAccount` endpoints plus a did:plc tombstone.
5	//
6	// A removal has three network/local effects, applied in a strict order:
7	//   1. deleteAccount   — the PDS purges all account data and emits an `#account`
8	//                        (`status="deleted"`) firehose frame relays consume.
9	//   2. plc_tombstone   — the wallet signs a tombstone with the DID's device key
10	//                        (rotationKeys[0]) and POSTs it to plc.directory, so the
11	//                        did:plc itself is retired network-wide (the PDS cannot do
12	//                        this — it never holds the rotation key, ADR-0001).
13	//   3. local wipe      — `IdentityStore::remove_identity` deletes every per-DID
14	//                        Keychain entry.
15	//
16	// Ordering invariant: the local wipe runs LAST and only after the tombstone
17	// submits, because the wipe deletes the device key that signs the tombstone. If the
18	// tombstone submit fails, the account is already deleted (its single-use email token
19	// spent) but the device key survives — the UI resumes via `tombstone_identity`, which
20	// retries only the tombstone + wipe.
21	
22	use serde::Serialize;
23	
24	use crate::identity_store::{IdentityStore, PerDidSignError};
25	use crate::pds_client::{PdsClient, PdsClientError};
26	use crate::session_provider::{SessionError, SessionProvider, UnlockReason};
27	
28	/// Keychain account holding the durable "removal in progress (post-delete)" index:
29	/// a JSON array of DIDs whose PDS account was deleted but whose tombstone + local
30	/// wipe has not yet completed. This is the recovery marker that makes a removal
31	/// interrupted after `deleteAccount` (e.g. iOS killing the app mid-tombstone)
32	/// resumable — on launch the UI reconciles any listed DID straight to the
33	/// tombstone-only retry rather than the full request flow (which would fail against
34	/// the already-deleted account).
35	const PENDING_REMOVALS_ACCOUNT: &str = "pending-removals";
36	
37	/// Load the set of DIDs with a pending post-delete removal, propagating a genuine
38	/// Keychain read failure.
39	///
40	/// A missing entry is an empty set, and corrupt JSON reads as empty (the marker is a
41	/// best-effort payload — a decode failure must not wedge the flow). But a real
42	/// Keychain security/IO error is returned, NOT swallowed: the mutators
43	/// (`mark_removal_pending` / `clear_removal_pending`) do a read-modify-write, so
44	/// silently treating a transient read failure as "empty" would let the subsequent
45	/// save overwrite the Keychain and drop any *other* DIDs' pending markers.
46	fn load_pending_removals_strict() -> Result<Vec<String>, crate::keychain::KeychainError> {
47	    match crate::keychain::get_item(PENDING_REMOVALS_ACCOUNT) {
48	        Ok(bytes) => Ok(serde_json::from_slice::<Vec<String>>(&bytes).unwrap_or_else(|e| {
49	            tracing::warn!(error = %e, "pending-removals Keychain entry is not valid JSON; treating as empty");
50	            Vec::new()
51	        })),
52	        Err(e) if crate::keychain::is_not_found(&e) => Ok(Vec::new()),
53	        Err(e) => Err(e),
54	    }
55	}
56	
57	/// Best-effort read of the pending-removal set for the infallible launch check.
58	///
59	/// Any Keychain trouble reads as an empty set — `list_pending_removals` is called
60	/// unconditionally on every launch and must never surface an error that could block it.
61	/// Read-modify-write callers must use [`load_pending_removals_strict`] instead, so a
62	/// transient read failure cannot clobber unrelated markers.
63	fn load_pending_removals() -> Vec<String> {
64	    load_pending_removals_strict().unwrap_or_else(|e| {
65	        tracing::warn!(error = %e, "Keychain error loading pending-removals; treating as empty");
66	        Vec::new()
67	    })
68	}
69	
70	/// Persist the pending-removals set. An empty set deletes the entry entirely so the
71	/// Keychain never carries a stale `[]`.
72	fn save_pending_removals(dids: &[String]) -> Result<(), crate::keychain::KeychainError> {
73	    if dids.is_empty() {
74	        return match crate::keychain::delete_item(PENDING_REMOVALS_ACCOUNT) {
75	            Ok(()) => Ok(()),
76	            Err(e) if crate::keychain::is_not_found(&e) => Ok(()),
77	            Err(e) => Err(e),
78	        };
79	    }
80	    // Vec<String> → JSON is infallible; unwrap keeps the signature Keychain-only.
81	    let json = serde_json::to_vec(dids).expect("Vec<String> always serializes to JSON");
82	    crate::keychain::store_item(PENDING_REMOVALS_ACCOUNT, &json)
83	}
84	
85	/// Mark `did` as having a pending post-delete removal (idempotent).
86	///
87	/// Called the instant `deleteAccount` succeeds, before the tombstone network round
88	/// trip — the step iOS is most likely to interrupt by backgrounding the app.
89	fn mark_removal_pending(did: &str) -> Result<(), crate::keychain::KeychainError> {
90	    let mut dids = load_pending_removals_strict()?;
91	    if !dids.iter().any(|d| d == did) {
92	        dids.push(did.to_string());
93	        save_pending_removals(&dids)?;
94	    }
95	    Ok(())
96	}
97	
98	/// Clear `did`'s pending-removal marker once the tombstone + wipe have completed.
99	fn clear_removal_pending(did: &str) -> Result<(), crate::keychain::KeychainError> {
100	    let mut dids = load_pending_removals_strict()?;
101	    let before = dids.len();
102	    dids.retain(|d| d != did);
103	    if dids.len() != before {
104	        save_pending_removals(&dids)?;
105	    }
106	    Ok(())
107	}
108	
109	/// Best-effort clear of the pending-removal marker after a successful removal.
110	///
111	/// A failure here is non-fatal: the removal already succeeded, and a lingering marker
112	/// only re-offers the (now idempotent, wipe-only) tombstone retry on the next launch,
113	/// which clears it. Never fail the removal over marker cleanup.
114	fn clear_removal_pending_best_effort(did: &str) {
115	    if let Err(e) = clear_removal_pending(did) {
116	        tracing::warn!(did = did, error = %e, "failed to clear pending-removal marker after removal");
117	    }
118	}
119	
120	/// Errors from the identity-removal flow.
121	///
122	/// Serializes as `{ "code": "SCREAMING_SNAKE_CASE", ... }` to match the other wallet
123	/// error enums (`RecoveryError`, `SessionError`, …). Variants are ordered by the step
124	/// that produces them so the UI can tell what already happened — notably, a
125	/// `PlcDirectoryError`/`RateLimited`/`NetworkError` *after* `InvalidToken` succeeded
126	/// means the PDS account is gone and only the tombstone + wipe remain (resume via
127	/// `tombstone_identity`).
128	#[derive(Debug, Serialize, thiserror::Error)]
129	#[serde(
130	    tag = "code",
131	    rename_all = "SCREAMING_SNAKE_CASE",
132	    rename_all_fields = "camelCase"
133	)]
134	pub enum RemovalError {
135	    /// The identity has no usable session; the UI must run the passwordless
136	    /// `sovereignLogin(did)` unlock before requesting deletion.
137	    #[error("identity needs a passwordless unlock before removal")]
138	    SessionRequired { reason: UnlockReason },
139	    /// `requestAccountDelete` failed (could not mint/send the confirmation code).
140	    #[error("failed to request account deletion: {message}")]
141	    RequestDeleteFailed { message: String },
142	    /// The PDS rejected the account password or the emailed confirmation code.
143	    #[error("invalid password or confirmation code")]
144	    InvalidToken,
145	    /// `deleteAccount` failed for a reason other than bad credentials.
146	    #[error("account deletion failed: {message}")]
147	    AccountDeleteFailed { message: String },
148	    /// The DID's plc.directory audit log could not be fetched/parsed for the tombstone `prev`.
149	    #[error("could not read the identity's PLC log: {message}")]
150	    InvalidAuditLog { message: String },
151	    /// Building or signing the tombstone with the device key failed.
152	    #[error("failed to sign the tombstone: {message}")]
153	    TombstoneSigningFailed { message: String },
154	    /// plc.directory rejected the tombstone. The account is already deleted — retry via
155	    /// `tombstone_identity`.
156	    #[error("plc.directory rejected the tombstone: {message}")]
157	    PlcDirectoryError { message: String },
158	    /// The DID's device key / managed-dids entry is missing.
159	    #[error("identity not found: {message}")]
160	    IdentityNotFound { message: String },
161	    /// The account was deleted and tombstoned, but the local Keychain wipe failed.
162	    #[error("local cleanup failed after removal: {message}")]
163	    LocalWipeFailed { message: String },
164	    /// A server rate-limited a step; the UI can retry after `retryAfter`.
165	    #[error("rate limited")]
166	    RateLimited { retry_after: Option<String> },
167	    /// Transport failure reaching the PDS or plc.directory.
168	    #[error("network error: {message}")]
169	    NetworkError { message: String },
170	}
171	
172	/// The successful result of a removal (or a `tombstone_identity` resume).
173	#[derive(Debug, Serialize, Clone, PartialEq, Eq)]
174	#[serde(rename_all = "camelCase")]
175	pub struct RemovalOutcome {
176	    /// The CID of the submitted did:plc tombstone operation.
177	    pub tombstone_cid: String,
178	    /// `true` if the removed DID was the last managed identity — the UI returns to
179	    /// onboarding rather than the identity list.
180	    pub was_last_identity: bool,
181	}
182	
183	/// Map a `deleteAccount` `PdsClientError` onto the removal error surface.
184	///
185	/// A 401 (wrong password) and a 400 `INVALID_TOKEN` (bad/expired confirmation code)
186	/// both collapse to `InvalidToken` — the UI re-prompts for both — while other XRPC
187	/// failures are a distinct `AccountDeleteFailed`.
188	fn map_delete_account_error(e: PdsClientError) -> RemovalError {
189	    match e {
190	        PdsClientError::Unauthorized { .. } => RemovalError::InvalidToken,
191	        PdsClientError::XrpcError { status: 400, .. } => RemovalError::InvalidToken,
192	        PdsClientError::RateLimited { retry_after, .. } => {
193	            RemovalError::RateLimited { retry_after }
194	        }
195	        PdsClientError::NetworkError { message } => RemovalError::NetworkError { message },
196	        other => RemovalError::AccountDeleteFailed {
197	            message: other.to_string(),
198	        },
199	    }
200	}
201	
202	/// Map a `requestAccountDelete` `PdsClientError` onto the removal error surface.
203	fn map_request_delete_error(e: PdsClientError) -> RemovalError {
204	    match e {
205	        PdsClientError::RateLimited { retry_after, .. } => {
206	            RemovalError::RateLimited { retry_after }
207	        }
208	        PdsClientError::NetworkError { message } => RemovalError::NetworkError { message },
209	        other => RemovalError::RequestDeleteFailed {
210	            message: other.to_string(),
211	        },
212	    }
213	}
214	
215	/// Map a `SessionProvider` failure onto the removal error surface.
216	fn map_session_error(e: SessionError) -> RemovalError {
217	    match e {
218	        SessionError::NeedsUnlock { reason } => RemovalError::SessionRequired { reason },
219	        SessionError::IdentityNotFound => RemovalError::IdentityNotFound {
220	            message: "no managed identity for this DID".to_string(),
221	        },
222	        SessionError::RateLimited { retry_after } => RemovalError::RateLimited { retry_after },
223	        SessionError::Offline { message } => RemovalError::NetworkError { message },
224	        other => RemovalError::RequestDeleteFailed {
225	            message: other.to_string(),
226	        },
227	    }
228	}
229	
230	/// Submit the tombstone, then — only if that succeeded — run the local wipe.
231	///
232	/// Split out so the ordering invariant ("the wipe never runs on a submit failure",
233	/// which keeps the device key alive for a `tombstone_identity` retry) is unit-testable
234	/// without a Keychain or a live plc.directory.
235	async fn submit_then_wipe<Submit, Wipe>(submit: Submit, wipe: Wipe) -> Result<(), RemovalError>
236	where
237	    Submit: std::future::Future<Output = Result<(), RemovalError>>,
238	    Wipe: FnOnce() -> Result<(), RemovalError>,
239	{
240	    submit.await?;
241	    wipe()
242	}
243	
244	/// Build + sign + submit the did:plc tombstone, then wipe local Keychain material.
245	///
246	/// Shared by `confirm_identity_removal` (after the PDS account is deleted) and
247	/// `tombstone_identity` (the resume path, where the account is already gone). Returns
248	/// the tombstone CID on success.
249	async fn tombstone_and_wipe(pds_client: &PdsClient, did: &str) -> Result<String, RemovalError> {
250	    let store = IdentityStore;
251	
252	    // 1. Fetch + parse the audit log and locate the head (newest non-nullified) operation.
253	    let audit_log_json =
254	        pds_client
255	            .fetch_audit_log(did)
256	            .await
257	            .map_err(|e| RemovalError::InvalidAuditLog {
258	                message: format!("failed to fetch audit log: {e}"),
259	            })?;
260	    let audit_log =
261	        crypto::parse_audit_log(&audit_log_json).map_err(|e| RemovalError::InvalidAuditLog {
262	            message: format!("failed to parse audit log: {e}"),
263	        })?;
264	    let head = audit_log
265	        .iter()
266	        .rev()
267	        .find(|e| !e.nullified)
268	        .ok_or_else(|| RemovalError::InvalidAuditLog {
269	            message: "audit log has no non-nullified operation to chain onto".to_string(),
270	        })?;
271	    let head_cid = head.cid.clone();
272	
273	    // Idempotent resume: if the DID is already tombstoned (its head IS a tombstone), the
274	    // submit already landed on plc.directory — only the local wipe remains. Submitting a
275	    // second tombstone would be rejected (a retired DID accepts no further ops), so a resume
276	    // after a wipe-only failure must skip straight to the wipe. This is what makes
277	    // `tombstone_identity` safe to call after a partial success.
278	    let head_is_tombstone =
279	        head.operation.get("type").and_then(|t| t.as_str()) == Some("plc_tombstone");
280	    if head_is_tombstone {
281	        wipe_local(&store, did)?;
282	        return Ok(head_cid);
283	    }
284	
285	    // The tombstone chains onto the head and must be signed by one of the head op's
286	    // `rotationKeys`. Verifying against those (not merely the local device key) is what
287	    // proves the wallet's key is still a *current* rotation key — the exact authorization
288	    // plc.directory will enforce — so a device key that is no longer in the rotation set
289	    // (e.g. after a migrate-away) fails fast locally instead of after the network round trip.
290	    let head_rotation_keys = extract_rotation_keys(&head.operation);
291	    if head_rotation_keys.is_empty() {
292	        return Err(RemovalError::InvalidAuditLog {
293	            message: "head operation has no rotationKeys to authorize the tombstone".to_string(),
294	        });
295	    }
296	
297	    // 2. Obtain the per-DID device-key signing closure (rotationKeys[0]).
298	    let sign = crate::identity_store::per_did_sign_closure(did).map_err(|e| match e {
299	        PerDidSignError::DeviceKeyNotFound { message } => {
300	            RemovalError::IdentityNotFound { message }
301	        }
302	        PerDidSignError::SigningSetupFailed { message } => {
303	            RemovalError::TombstoneSigningFailed { message }
304	        }
305	    })?;
306	
307	    // 3. Build + sign the tombstone (prev = the head CID).
308	    let tombstone = crypto::build_did_plc_tombstone_op(&head_cid, sign).map_err(|e| {
309	        RemovalError::TombstoneSigningFailed {
310	            message: format!("failed to build tombstone: {e}"),
311	        }
312	    })?;
313	
314	    // 3b. Local self-check against the head op's authorized rotation keys (see above).
315	    crypto::verify_plc_tombstone_op(&tombstone.signed_op_json, &head_rotation_keys).map_err(
316	        |e| RemovalError::TombstoneSigningFailed {
317	            message: format!("tombstone self-verification failed: {e}"),
318	        },
319	    )?;
320	
321	    let op_value: serde_json::Value =
322	        serde_json::from_str(&tombstone.signed_op_json).map_err(|e| {
323	            RemovalError::TombstoneSigningFailed {
324	                message: format!("failed to parse signed tombstone JSON: {e}"),
325	            }
326	        })?;
327	
328	    // 4. Submit to plc.directory, THEN (only on success) 5. wipe local material.
329	    //    Every failure in this function is post-delete (the account is already gone when
330	    //    `confirm_identity_removal` calls us), so PLC-submit transport/rate-limit failures
331	    //    fold into `PlcDirectoryError` rather than the bare `NetworkError`/`RateLimited` the
332	    //    deletion stage uses — that keeps the two stages' error codes disjoint, so the UI
333	    //    only enters the tombstone-retry path for genuinely post-delete failures.
334	    let did_owned = did.to_string();
335	    submit_then_wipe(
336	        async {
337	            pds_client
338	                .post_plc_operation(&did_owned, &op_value)
339	                .await
340	                .map_err(|e| RemovalError::PlcDirectoryError {
341	                    message: format!("plc.directory rejected the tombstone: {e}"),
342	                })
343	        },
344	        || wipe_local(&store, &did_owned),
345	    )
346	    .await?;
347	
348	    Ok(tombstone.cid)
349	}
350	
351	/// Extract a PLC operation's `rotationKeys` as typed did:key URIs (empty if absent/malformed).
352	fn extract_rotation_keys(operation: &serde_json::Value) -> Vec<crypto::DidKeyUri> {
353	    operation
354	        .get("rotationKeys")
355	        .and_then(|v| v.as_array())
356	        .map(|arr| {
357	            arr.iter()
358	                .filter_map(|v| v.as_str().map(|s| crypto::DidKeyUri(s.to_string())))
359	                .collect()
360	        })
361	        .unwrap_or_default()
362	}
363	
364	/// Wipe the DID's local Keychain material. Best-effort and idempotent: a missing
365	/// managed-dids entry (already removed by a prior partial run) is success, not failure.
366	fn wipe_local(store: &IdentityStore, did: &str) -> Result<(), RemovalError> {
367	    match store.remove_identity(did) {
368	        Ok(()) => Ok(()),
369	        Err(crate::identity_store::IdentityStoreError::IdentityNotFound) => Ok(()),
370	        Err(e) => Err(RemovalError::LocalWipeFailed {
371	            message: format!("failed to wipe local identity material: {e}"),
372	        }),
373	    }
374	}
375	
376	/// `true` if no managed identities remain — the UI returns to onboarding rather than the
377	/// identity list. Shared by the tombstone-completing paths and the local-only forget path.
378	fn no_identities_remain() -> Result<bool, RemovalError> {
379	    IdentityStore
380	        .list_identities()
381	        .map(|ids| ids.is_empty())
382	        .map_err(|e| RemovalError::LocalWipeFailed {
383	            message: format!("failed to re-read managed identities: {e}"),
384	        })
385	}
386	
387	/// Compute the `RemovalOutcome` after a successful `tombstone_and_wipe`.
388	fn removal_outcome(tombstone_cid: String) -> Result<RemovalOutcome, RemovalError> {
389	    Ok(RemovalOutcome {
390	        tombstone_cid,
391	        was_last_identity: no_identities_remain()?,
392	    })
393	}
394	
395	/// Tauri command: request permanent deletion — emails a single-use confirmation code.
396	///
397	/// Obtains a full-access session for `did` (the frontend runs the passwordless unlock
398	/// first if this returns `SessionRequired`) and calls `requestAccountDelete`. The PDS
399	/// emails a 1-hour code to the account address; the user then supplies that code plus
400	/// the account password to `confirm_identity_removal`.
401	#[tauri::command]
402	pub async fn request_identity_removal(
403	    state: tauri::State<'_, crate::oauth::AppState>,
404	    did: String,
405	) -> Result<(), RemovalError> {
406	    let now =
407	        crate::sovereign_session::unix_timestamp().map_err(|_| RemovalError::NetworkError {
408	            message: "system clock is unavailable".to_string(),
409	        })?;
410	    let session = SessionProvider
411	        .full_access_client(state.pds_client(), &IdentityStore, &did, now)
412	        .await
413	        .map_err(map_session_error)?;
414	
415	    crate::pds_client::request_account_delete(&session.client)
416	        .await
417	        .map_err(map_request_delete_error)
418	}
419	
420	/// Tauri command: confirm removal — delete on the PDS, tombstone the DID, wipe locally.
421	///
422	/// `password` is the account password (set during the DID ceremony); `token` is the
423	/// emailed confirmation code. `deleteAccount` is attempted FIRST, so a wrong
424	/// password/code (`InvalidToken`) leaves everything intact and the UI re-prompts. Once
425	/// the account is deleted, the tombstone + wipe run via `tombstone_and_wipe`.
426	#[tauri::command]
427	pub async fn confirm_identity_removal(
428	    state: tauri::State<'_, crate::oauth::AppState>,
429	    did: String,
430	    password: String,
431	    token: String,
432	) -> Result<RemovalOutcome, RemovalError> {
433	    // The account's PDS base URL comes from its still-present token record (the wipe is
434	    // last). Falling back to live discovery keeps a stale/absent record from stranding
435	    // an otherwise-deletable account.
436	    let pds_url = resolve_pds_url(state.pds_client(), &did).await?;
437	
438	    // 1. Permanently delete the account on the PDS (body-authed; no session needed).
439	    state
440	        .pds_client()
441	        .delete_account(&pds_url, &did, &password, &token)
442	        .await
443	        .map_err(map_delete_account_error)?;
444	
445	    // The account is now permanently gone and the single-use email code is spent — from
446	    // here on, only the tombstone + local wipe remain. Persist a durable marker BEFORE the
447	    // tombstone's network round trip so that if iOS kills/suspends the app mid-tombstone,
448	    // the next launch resumes via `tombstone_identity` rather than the request flow (which
449	    // would fail against the deleted account). A marker-write failure is logged but never
450	    // blocks the removal: the account is already deleted, so aborting here would only strand
451	    // the identity harder.
452	    if let Err(e) = mark_removal_pending(&did) {
453	        tracing::warn!(did = %did, error = %e, "failed to persist pending-removal marker after deleteAccount");
454	    }
455	
456	    // 2 + 3. Tombstone the did:plc, then wipe local material.
457	    let tombstone_cid = tombstone_and_wipe(state.pds_client(), &did).await?;
458	    clear_removal_pending_best_effort(&did);
459	    removal_outcome(tombstone_cid)
460	}
461	
462	/// Tauri command: resume a removal whose PDS account was already deleted.
463	///
464	/// Used when `confirm_identity_removal` deleted the account but the tombstone or wipe
465	/// failed: the single-use deletion token is already spent, so re-running `confirm`
466	/// would 401 at `deleteAccount`. `tombstone_and_wipe` is idempotent — if the tombstone
467	/// already landed (the DID's head is a tombstone), it does a wipe-only retry rather than
468	/// submitting a second, doomed operation; otherwise it completes the tombstone + wipe.
469	#[tauri::command]
470	pub async fn tombstone_identity(
471	    state: tauri::State<'_, crate::oauth::AppState>,
472	    did: String,
473	) -> Result<RemovalOutcome, RemovalError> {
474	    let tombstone_cid = tombstone_and_wipe(state.pds_client(), &did).await?;
475	    clear_removal_pending_best_effort(&did);
476	    removal_outcome(tombstone_cid)
477	}
478	
479	/// Tauri command: list DIDs with a pending post-delete removal.
480	///
481	/// Backs the launch-time reconciliation: if a removal deleted the PDS account but was
482	/// interrupted before the tombstone + wipe finished, the DID stays listed here so the UI
483	/// can resume it (idempotent `tombstone_identity`) instead of re-entering the request
484	/// flow. Infallible — any Keychain/decoding trouble reads as an empty list, so it can be
485	/// called unconditionally on every launch.
486	#[tauri::command]
487	pub fn list_pending_removals() -> Vec<String> {
488	    load_pending_removals()
489	}
490	
491	/// Tauri command: forget an identity's local material WITHOUT any network step.
492	///
493	/// The escape hatch for an identity that can no longer be removed through the normal flow
494	/// because its PDS account no longer exists — deleted from another device, purged
495	/// server-side, or migrated away. In every such case the deletion endpoints can only answer
496	/// with an opaque 401: the PDS deliberately does not expose account existence, so an unknown
497	/// DID and a wrong password are indistinguishable (see
498	/// `crates/pds/src/routes/delete_account.rs`). The request/confirm flow can therefore never
499	/// make progress, and without this the identity would be stranded in the wallet forever.
500	///
501	/// This wipes the DID's Keychain material and clears any pending-removal marker. It
502	/// deliberately does NOT tombstone the did:plc: the DID may already be retired, or (the
503	/// migrate-away case) the device key is no longer a rotation key and the identity now lives
504	/// on another PDS — so "forget locally" only promises to remove the identity from THIS
505	/// device. The frontend states that plainly and gates the call behind the biometric prompt.
506	///
507	/// Returns `was_last_identity` (mirroring `RemovalOutcome`) so the UI can route back to
508	/// onboarding rather than the identity list when the wallet is now empty.
509	#[tauri::command]
510	pub fn forget_identity_locally(did: String) -> Result<bool, RemovalError> {
511	    wipe_local(&IdentityStore, &did)?;
512	    clear_removal_pending_best_effort(&did);
513	    no_identities_remain()
514	}
515	
516	/// Resolve the PDS base URL for `did`: the stored token record first, then live
517	/// discovery. Used only to address the body-authed `deleteAccount` endpoint.
518	async fn resolve_pds_url(pds_client: &PdsClient, did: &str) -> Result<String, RemovalError> {
519	    if let Ok(Some(record)) = IdentityStore.load_oauth_tokens(did) {
520	        if !record.pds_url.is_empty() {
521	            return Ok(record.pds_url);
522	        }
523	    }
524	    let (pds_url, _doc) =
525	        pds_client
526	            .discover_pds(did)
527	            .await
528	            .map_err(|e| RemovalError::NetworkError {
529	                message: format!("could not resolve the identity's PDS: {e}"),
530	            })?;
531	    Ok(pds_url)
532	}
