22	  let {
23	    did,
24	    handle,
25	    onback,
26	    oncomplete,
27	  }: {
28	    did: string;
29	    /** The identity's handle (for context in the warning); may be empty. */
30	    handle?: string;
31	    onback: () => void;
32	    /** Called on success. `wasLast` routes back to onboarding vs. the identity list. */
33	    oncomplete: (wasLast: boolean) => void;
34	  } = $props();
35	
36	  // warn → confirm (code + password) → (on partial failure) tombstone_retry.
37	  // forget_confirm is the local-only escape hatch, reachable whenever the server-side
38	  // deletion can't proceed (the account no longer exists on its PDS).
39	  type Phase =
40	    | 'warn'
41	    | 'requesting'
42	    | 'confirm'
43	    | 'working'
44	    | 'tombstone_retry'
45	    | 'forget_confirm';
46	  let phase = $state<Phase>('warn');
47	  let error = $state<string | null>(null);
48	
49	  let code = $state('');
50	  let password = $state('');
51	
52	  let canConfirm = $derived(code.trim().length > 0 && password.length > 0);
53	
54	  // If a prior attempt already deleted the PDS account but was interrupted before the
55	  // tombstone + wipe finished (the app was killed mid-flow), the account is gone and the
56	  // single-use email code is spent — the request flow would fail. Resume straight to the
57	  // tombstone-only retry instead. Checked on every mount so this self-corrects no matter
58	  // how the screen was reached (launch reconciliation or manual navigation).
59	  onMount(async () => {
60	    try {
61	      const pending = await listPendingRemovals();
62	      if (pending.includes(did) && phase === 'warn') {
63	        phase = 'tombstone_retry';
64	      }
65	    } catch (e) {
66	      console.warn('listPendingRemovals failed:', e);
67	    }
68	  });
69	
70	  // Hold-to-remove: a deliberate, irreversible confirmation gesture (matches the
71	  // recovery-override screen), gated by biometrics before anything is sent.
72	  const HOLD_MS = 1500;
73	  const hold = useHoldGesture({
74	    durationMs: HOLD_MS,
75	    oncomplete: () => {
76	      hold.state.progress = 1;
77	      confirm();
78	    },
79	    canStart: () => phase === 'confirm' && canConfirm,
80	  });
81	  let holdFill = $derived(hold.state.progress);
82	
83	  // A separate hold gesture for the "forget" confirmation, so its own progress and canStart
84	  // guard stay independent of the delete-and-tombstone hold above.
85	  const forgetHold = useHoldGesture({
86	    durationMs: HOLD_MS,
87	    oncomplete: () => {
88	      forgetHold.state.progress = 1;
89	      confirmForget();
90	    },
91	    canStart: () => phase === 'forget_confirm',
92	  });
93	  let forgetHoldFill = $derived(forgetHold.state.progress);
94	
95	  // Advanced escape-hatch options, revealed behind a disclosure. `alsoTombstone` upgrades the
96	  // local-only wipe into a full network retirement (sign + publish a did:plc tombstone) for an
97	  // advanced user who is certain they want to torch the identity everywhere, not just here.
98	  let showAdvanced = $state(false);
99	  let alsoTombstone = $state(false);
100	
101	  // The message shown during the `working` step — set by each path so it tells the literal truth
102	  // (a local-only forget must not claim it is "deleting your account").
103	  let workingMessage = $state('Removing identity…');
104	
105	  /** Enter the escape hatch from any stuck state, resetting its advanced options. */
106	  function startForget() {
107	    error = null;
108	    showAdvanced = false;
109	    alsoTombstone = false;
110	    phase = 'forget_confirm';
111	  }
112	
113	  /** Translate a typed RemovalError (or any throwable) into a display string. */
114	  function messageFor(raw: unknown): string {
115	    if (isCodedError(raw)) {
116	      const err = raw as RemovalError;
117	      switch (err.code) {
118	        case 'SESSION_REQUIRED':
119	          return 'This identity needs to be unlocked first.';
120	        case 'REQUEST_DELETE_FAILED':
121	          return `Could not start deletion: ${err.message || 'unknown error'}`;
122	        case 'INVALID_TOKEN':
123	          return 'That password or confirmation code was not accepted. Check your email and try again.';
124	        case 'ACCOUNT_DELETE_FAILED':
125	          return `Account deletion failed: ${err.message || 'unknown error'}`;
126	        case 'INVALID_AUDIT_LOG':
