const btns = [...document.querySelectorAll('button')];
const card = btns.find(b => b.textContent.includes('web.example.com'));
card.click();
JSON.stringify({ clicked: !!card, text: document.body.innerText.slice(0, 300) })

// rAF does not fire in the hidden browser pane; the hold gesture drives its progress from it.
window.requestAnimationFrame = (cb) => setTimeout(() => cb(performance.now()), 16);
const set = (el, v) => {
  const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement : HTMLInputElement;
  Object.getOwnPropertyDescriptor(proto.prototype, 'value').set.call(el, v);
  el.dispatchEvent(new Event('input', { bubbles: true }));
};
const inputs = [...document.querySelectorAll('input')];
set(inputs[0], 'CODE123');
set(inputs[1], 'hunter2');
JSON.stringify(inputs.map(i => ({ type: i.type, value: i.value })))

const hold = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Hold to remove'));
hold.focus();
hold.dispatchEvent(new KeyboardEvent('keydown', { key: ' ', bubbles: true }));
'holding'

[...document.querySelectorAll('button')].find(b => b.textContent.trim() === 'Done').click();
JSON.stringify({ removed: !window.__harness.state().identities.some(i => i.did === 'did:web:web.example.com'),
                 remaining: window.__harness.state().identities.map(i => i.did) })

window.requestAnimationFrame = (cb) => setTimeout(() => cb(performance.now()), 16);
[...document.querySelectorAll('button')].find(b => b.textContent.trim() === 'Continue').click();
setTimeout(() => {
  const set = (el, v) => {
    Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(el, v);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  };
  const inputs = [...document.querySelectorAll('input')];
  set(inputs[0], 'CODE123'); set(inputs[1], 'hunter2');
